public class Triangulo extends Forma {private double a,b,c;public Triangulo(String cor,double a,double b,double c){super(cor);this.a=a;this.b=b;this.c=c;}@Override public double calcularArea(){double s=(a+b+c)/2;return Math.sqrt(s*(s-a)*(s-b)*(s-c));}@Override public double calcularPerimetro(){return a+b+c;}}
